harness.helpers:
/// An ISM that accepts every message: the worst case for the lockbox's own checks.
contract SpecIsm {
    function moduleType() external pure returns (uint8) { return 5; }
    function verify(bytes calldata, bytes calldata) external pure returns (bool) { return true; }
}

harness.state:
MockMailbox public mailbox;
bytes32 public constant OUTBOX = bytes32(uint256(0x0b0b));
uint256 public sumLocked;
uint256 public sumReleased;
bytes32[] public ids;

harness.setup:
mailbox = new MockMailbox(11155111);
t = new HyperlaneLockBoxV2(ISaphanMailbox(address(mailbox)), 77390, 77390, bytes32(uint256(0x1a2e)), OUTBOX, address(0),
    ISaphanIsm(address(new SpecIsm())), address(0x6070), address(0x6A2D), 10 ether, 0);
vm.deal(address(this), 5 ether);
t.lock{value: 5 ether}(address(0xB0B), 5 ether);
sumLocked = 5 ether;

actions.handle:
// any release message the (all-accepting) ISM lets through: any nonce, sender, receiver and amount
bytes memory b = abi.encode(uint256(77390), address(uint160(uint256(OUTBOX))), a[0], address(uint160(a[1])), address(uint160(a[2])),
    uint256(uint96(a[3])), block.chainid, address(t));
vm.prank(address(mailbox));
try t.handle(77390, OUTBOX, b) { ok = true; ids.push(keccak256(b)); } catch { ok = false; }

actions.claim:
if (ids.length == 0) return false;
bytes32 id = ids[a[0] % ids.length];
(, , , , uint256 amount) = t.releases(id);
vm.prank(caller);
try t.claim(id) { ok = true; sumReleased += amount; } catch { ok = false; }

actions.veto:
if (ids.length == 0) return false;
vm.prank(caller);
try t.veto(ids[a[0] % ids.length]) { ok = true; } catch { ok = false; }
